const BASE = "https://storage.googleapis.com/driftwood-oruk-faire";
const portrait = () => window.matchMedia('(orientation: portrait)').matches || window.innerWidth < 700;
function srcFor(c){ return `${BASE}/${c.s}-oruk-${portrait() ? '9x16' : '16x9'}.mp4` }
const PLAN = {SUPPORT:"A support call about your product, scored after it ends.", VOICE_AGENT:"A customer talking to your agent, graded on how they sounded.", CONTENT:"A scene from your own library, oruk reading every line.", GENERIC:"oruk’s flagship demo, with your name on it."};
const norm = s => s.toLowerCase().replace(/[^a-z0-9]/g,"");
const q = document.getElementById('q'), list = document.getElementById('list'), res = document.getElementById('result');
function matches(v){ const n = norm(v); if(!n) return []; const rank = c => { const names = [c.n, ...c.a].map(norm); if (names.includes(n)) return 0; if (names.some(x => x.startsWith(n))) return 1; return names.some(x => x.includes(n)) ? 2 : 9 }; return C.map(c => [rank(c), c]).filter(([r]) => r < 9).sort((a, b) => a[0] - b[0] || a[1].n.length - b[1].n.length).slice(0, 8).map(([, c]) => c) }
let current = null;
function pick(c){ current = c; q.value = c.n; list.classList.remove('on'); const v = document.getElementById('v'); v.src = srcFor(c); v.load(); document.getElementById('rn').textContent = c.n; const lg = document.getElementById('rlogo'); if (c.logo) { lg.src = `${BASE}/logos/${c.s}.png`; lg.alt = c.n; lg.style.display = 'block' } else { lg.style.display = 'none' }; document.getElementById('rp').textContent = PLAN[c.plan] + (c.product ? " (" + c.product + ")" : ""); document.getElementById('rk').textContent = "Your demo"; document.getElementById('cap').classList.remove('on'); res.classList.add('on'); res.scrollIntoView({behavior:'smooth',block:'start'}) }
function notListed(){ current = null; list.classList.remove('on'); const v = document.getElementById('v'); v.src = `${BASE}/a16z-oruk-${portrait() ? '9x16' : '16x9'}.mp4`; v.load(); document.getElementById('rn').textContent = q.value.trim(); document.getElementById('rlogo').style.display = 'none'; document.getElementById('rp').textContent = "We don’t have yours yet. Watch how it works, and leave an email and we’ll make one for " + q.value.trim() + "."; document.getElementById('rk').textContent = "Not on our list yet"; document.getElementById('cap').classList.add('on'); res.classList.add('on') }
q.addEventListener('input', () => { const m = matches(q.value); list.innerHTML = m.map(c => `<button type="button" data-n="${c.n.replace(/"/g,'&quot;')}">${c.n}<span>${c.plan==='GENERIC'?'':c.plan.toLowerCase().replace('_',' ')}</span></button>`).join('') + (q.value.trim() ? `<button type="button" data-none="1">“${q.value.trim()}” isn’t listed · make mine<span>→</span></button>` : ''); list.classList.toggle('on', !!q.value.trim()) });
list.addEventListener('click', e => { const b = e.target.closest('button'); if(!b) return; if(b.dataset.none) return notListed(); pick(C.find(c => c.n === b.dataset.n)) });
q.addEventListener('keydown', e => { if(e.key === 'Enter') { const m = matches(q.value); m.length ? pick(m[0]) : notListed() } });
window.addEventListener('resize', () => { if (current) { const v = document.getElementById('v'); const t = v.currentTime, was = !v.paused; v.src = srcFor(current); v.load(); v.currentTime = t; if (was) v.play().catch(()=>{}) } });

const capSend = document.getElementById('capSend'); if (capSend) capSend.addEventListener('click', e => { e.preventDefault(); document.getElementById('cap').innerHTML = '<p class=note>Got it. We’ll send it within the day.</p>' });


/* Deep link: /oruk?c=<slug> (or ?company=<name>) opens that company's demo straight away —
   the link we put in outreach emails. Falls back to the search box when the slug is unknown. */
(function deepLink(){
  const p = new URLSearchParams(location.search);
  const want = (p.get('c') || p.get('company') || '').trim();
  if (!want) return;
  const k = norm(want);
  const hit = C.find(c => c.s === want.toLowerCase()) || C.find(c => [c.n, ...c.a].some(x => norm(x) === k));
  if (hit) { pick(hit); document.getElementById('result').scrollIntoView({behavior:'smooth', block:'center'}) }
  else { q.value = want; q.dispatchEvent(new Event('input')) }
})();
